// ?adjustPower@Energy@@QAEXH_N@Z
void Energy::adjustPower(int powerDelta, bool adding)
{
	if (powerDelta == 0)
		return;

	if (powerDelta > 0)
	{
		if (adding)
			addProduction(powerDelta);
		else
			addProduction(-powerDelta);
	}
	else
	{
		if (adding)
			addConsumption(-powerDelta);
		else
			addConsumption(powerDelta);
	}
}

